window.docContents[30].resolve({"/Aula-1___-Motiva______o-e-L___gica-Proposicional/Dedu______o-Natural/#Verifica______o-Formal-de-Software--Aula-1___-Motiva______o-e-L___gica-Proposicional--Dedu______o-Natural--Conjun______o":{"contents":"Para introduzir P ∧ Q, prove as duas partes. A eliminação projeta qualquer uma delas.\n\n   P    Q              P ∧ Q            P ∧ Q\n  ───────  ∧I         ───────  ∧E₁     ───────  ∧E₂\n   P ∧ Q                 P                Q\n\n\n","context":"Verificação Formal de Software\u0009Aula 1: Motivação e Lógica Proposicional\u0009Dedução Natural","header":"1.5.2. Conjunção","id":"/Aula-1___-Motiva______o-e-L___gica-Proposicional/Dedu______o-Natural/#Verifica______o-Formal-de-Software--Aula-1___-Motiva______o-e-L___gica-Proposicional--Dedu______o-Natural--Conjun______o"},"/Aula-1___-Motiva______o-e-L___gica-Proposicional/Dedu______o-Natural/#Verifica______o-Formal-de-Software--Aula-1___-Motiva______o-e-L___gica-Proposicional--Dedu______o-Natural--Disjun______o":{"contents":"Para introduzir P ∨ Q, prove um disjunto. Para eliminá-la, prove uma conclusão comum R a partir de cada disjunto por vez, descartando o disjunto suposto em cada ramo.\n\n     P                 Q                              [P]     [Q]\n  ───────  ∨I₁      ───────  ∨I₂          P ∨ Q         ⋮       ⋮\n   P ∨ Q             P ∨ Q                              R       R\n                                        ──────────────────────────  ∨E\n                                                     R\n\n\n","context":"Verificação Formal de Software\u0009Aula 1: Motivação e Lógica Proposicional\u0009Dedução Natural","header":"1.5.3. Disjunção","id":"/Aula-1___-Motiva______o-e-L___gica-Proposicional/Dedu______o-Natural/#Verifica______o-Formal-de-Software--Aula-1___-Motiva______o-e-L___gica-Proposicional--Dedu______o-Natural--Disjun______o"}});